import java.util.*;

class FileSystem {
  private static class Entry {
    TreeMap<String, Entry> children = new TreeMap<>(); // sorted names for ls
    StringBuilder content; // non-null means this entry is a file
  }

  private final Entry root = new Entry();

  public FileSystem() {}

  public List<String> ls(String path) {
    Entry e = walk(path, false);
    List<String> res = new ArrayList<>();
    if (e.content != null) res.add(path.substring(path.lastIndexOf('/') + 1));
    else res.addAll(e.children.keySet());
    return res;
  }

  public void mkdir(String path) {
    walk(path, true);
  }

  public void addContentToFile(String filePath, String content) {
    Entry e = walk(filePath, true);
    if (e.content == null) e.content = new StringBuilder();
    e.content.append(content);
  }

  public String readContentFromFile(String filePath) {
    return walk(filePath, false).content.toString();
  }

  private Entry walk(String path, boolean create) {
    Entry cur = root;
    for (String part : path.split("/")) {
      if (part.isEmpty()) continue;
      Entry next = cur.children.get(part);
      if (next == null && create) cur.children.put(part, next = new Entry());
      cur = next;
    }
    return cur;
  }
}
